const W=960,H=540,keys={},touch={};
let scene='title',last=0,clock=0,camera=0,toast='',toastTime=0,shake=0;
const player={x:92,y:380,w:27,h:44,vx:0,vy:0,face:1,hp:100,maxHp:100,mp:60,maxMp:60,level:1,xp:0,next:100,points:0,strength:1,magic:1,speed:1,weapon:0,spell:0,invuln:0,attack:0,cast:0,ground:false};
