function makeWorld(){platforms=[];platform(0,480,1120,60,'sand');platform(1170,480,510,60,'sand');platform(1680,480,1570,60,'stone');
 platform(300,408,145);platform(520,352,128);platform(780,408,160);platform(1050,365,110);platform(1210,410,145);platform(1415,350,145);platform(1735,405,155);platform(1975,350,135);platform(2190,400,165);platform(2435,345,130);platform(2700,400,165);platform(2950,360,120);
 enemies=[{x:430,y:438,w:28,h:42,hp:35,max:35,type:'skeleton',speed:43,dir:-1,x1:385,x2:490,xp:30},{x:700,y:438,w:28,h:42,hp:38,max:38,type:'skeleton',speed:48,dir:1,x1:660,x2:750,xp:30},{x:980,y:438,w:28,h:42,hp:45,max:45,type:'skeleton',speed:48,dir:-1,x1:930,x2:1040,xp:40},{x:1320,y:438,w:30,h:30,hp:28,max:28,type:'scarab',speed:72,dir:-1,x1:1280,x2:1390,xp:25},{x:1880,y:438,w:28,h:42,hp:50,max:50,type:'wraith',speed:52,dir:1,x1:1840,x2:1935,xp:45},{x:2110,y:438,w:30,h:30,hp:32,max:32,type:'scarab',speed:82,dir:-1,x1:2050,x2:2170,xp:30},{x:2360,y:438,w:28,h:42,hp:55,max:55,type:'wraith',speed:56,dir:-1,x1:2310,x2:2415,xp:50},{x:2640,y:438,w:28,h:42,hp:58,max:58,type:'wraith',speed:54,dir:1,x1:2570,x2:2680,xp:50}];
