 if(scene==='upgrade'){if(pressAction('1'))upgrade('strength');if(pressAction('2'))upgrade('health');if(pressAction('3'))upgrade('magic');if(pressAction('4'))upgrade('speed');if(pressAction('escape')||pressAction('e'))scene='play';return}
