function openChest(c){if(c.opened)return;c.opened=true;burst(c.x+16,c.y,'#ffc85e',12);if(c.kind==='weapon'){player.weapon=Math.min(weapons.length-1,player.weapon+1);message(`FOUND ${weapons[player.weapon].name}!`,2.4)}else if(c.kind==='heart'){player.maxHp+=35;player.hp=player.maxHp;message('HEART OF RA · VITALITY RESTORED',2.4)}else{player.spell=1;player.maxMp+=30;player.mp=player.maxMp;message('FOUND SCARAB STORM · MAGIC UPGRADED',2.4)}}
