function attack(){if(player.attack>0)return;player.attack=.25;const range=player.weapon===2?76:62;let hit=false;for(const e of enemies){if(e.hp>0&&Math.abs((e.x+e.w/2)-(player.x+player.w/2))<range&&Math.abs(e.y-player.y)<62&&Math.sign(e.x-player.x)===player.face){e.hp-=18+player.strength*8+weapons[player.weapon].power*10;e.hit=.18;burst(e.x+e.w/2,e.y+20,'#f2bd66',6);hit=true;if(e.hp<=0){addXP(e.xp);burst(e.x+14,e.y+22,'#bbd7c6',12)}}}if(boss?.alive&&Math.abs((boss.x+boss.w/2)-(player.x+player.w/2))<range+25&&Math.abs(boss.y-player.y)<90&&Math.sign(boss.x-player.x)===player.face){boss.hp-=14+player.strength*7+weapons[player.weapon].power*8;boss.hit=.2;burst(boss.x+boss.w/2,boss.y+45,'#ffd56e',9);hit=true;if(boss.hp<=0){boss.alive=false;addXP(180);player.weapon=Math.max(player.weapon,2);message('THE PHARAOH FALLS · OBSIDIAN FANG CLAIMED',4);burst(boss.x+40,boss.y+50,'#ffd767',36)}}if(!hit)burst(player.x+player.w/2+player.face*28,player.y+22,'#e6b96c',3)}
function cast(){if(player.cast>0||player.mp<18)return;player.mp-=18;player.cast=.38;shots.push({x:player.x+player.w/2+player.face*20,y:player.y+21,vx:player.face*330,life:1.6,power:25+player.magic*15+(player.spell?16:0),spell:player.spell});burst(player.x+player.w/2+player.face*21,player.y+20,player.spell?'#a1f0a9':'#ffe77b',5)}
function hurt(d){if(player.invuln>0)return;player.hp-=d;player.invuln=.8;shake=7;burst(player.x+13,player.y+20,'#e96d54',8);if(player.hp<=0){player.hp=0;scene='dead'}}
function update(dt){clock+=dt;if(toastTime>0)toastTime-=dt;if(shake>0)shake*=.82;for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=250*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);if(scene!=='play')return;
 const speed=172+player.speed*20;let dir=(pressAction('right')?1:0)-(pressAction('left')?1:0);player.vx=dir*speed;if(dir)player.face=dir;player.x=clamp(player.x+player.vx*dt,0,worldEnd-40);if(pressAction('jump')&&player.ground){player.vy=-430;player.ground=false}player.vy=Math.min(600,player.vy+1080*dt);player.y+=player.vy*dt;player.ground=false;
