 if(player.y>H+120)hurt(999);player.attack=Math.max(0,player.attack-dt);player.cast=Math.max(0,player.cast-dt);player.invuln=Math.max(0,player.invuln-dt);player.mp=Math.min(player.maxMp,player.mp+4*dt);
 if(pressAction('attack'))attack();if(pressAction('magic'))cast();if(pressAction('interact')){interact();keys.interact=false;touch.interact=false}
 for(const e of enemies){if(e.hp<=0)continue;e.x+=e.dir*e.speed*dt;if(e.x<e.x1||e.x>e.x2)e.dir*=-1;e.hit=Math.max(0,(e.hit||0)-dt);if(boxHit(player,e)&&player.invuln<=.01)hurt(e.type==='scarab'?9:12)}
 for(const s of shots){s.x+=s.vx*dt;s.life-=dt;for(const e of enemies){if(e.hp>0&&Math.abs(s.x-(e.x+e.w/2))<22&&Math.abs(s.y-(e.y+20))<32){e.hp-=s.power;burst(s.x,s.y,s.spell?'#a1f0a9':'#ffdf74',8);s.life=0;if(e.hp<=0)addXP(e.xp)}}if(boss?.alive&&Math.abs(s.x-(boss.x+boss.w/2))<54&&Math.abs(s.y-(boss.y+50))<66){boss.hp-=s.power;boss.hit=.2;s.life=0;burst(s.x,s.y,'#ffe26c',10);if(boss.hp<=0){boss.alive=false;addXP(180);player.weapon=2;message('THE PHARAOH FALLS · OBSIDIAN FANG CLAIMED',4);burst(boss.x+40,boss.y+50,'#ffd767',36)}}}shots=shots.filter(s=>s.life>0&&s.x>-50&&s.x<worldEnd+50);
 if(boss?.alive){boss.hit=Math.max(0,(boss.hit||0)-dt);boss.timer-=dt;if(Math.abs(player.x-boss.x)<195&&boss.timer<=0){boss.timer=1.8;boss.phase++;if(boss.phase%2){shots.push({x:boss.x+boss.w/2,y:boss.y+52,vx:Math.sign(player.x-boss.x)*205,life:2,power:0,boss:true});message('THE PHARAOH SUMMONS A CURSE!',1)}else{boss.x+=Math.sign(player.x-boss.x)*48;boss.dir=Math.sign(player.x-boss.x)}}if(boxHit(player,boss)&&player.invuln<=.01)hurt(18)}
 for(const s of shots){if(s.boss&&Math.abs(s.x-(player.x+13))<24&&Math.abs(s.y-(player.y+21))<26){hurt(14);s.life=0;burst(s.x,s.y,'#ce73b0',9)}}shots=shots.filter(s=>s.life>0);
 camera=clamp(player.x-W*.36,0,worldEnd-W);if(player.x>1570&&checkpoint===0){checkpoint=1;message('THE PYRAMID OF THE LOST · CHECKPOINT',3)}
}

