 for(let i=0;i<4;i++){let x=((i*350-camera*.13)%1300+1300)%1300-180,y=235+i%2*32;ctx.fillStyle=i%2?'#bd794f':'#a96749';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+95,y-95-i%2*30);ctx.lineTo(x+204,y);ctx.fill();ctx.fillStyle=i%2?'#d18a53':'#c27a4c';ctx.beginPath();ctx.moveTo(x+95,y-95-i%2*30);ctx.lineTo(x+204,y);ctx.lineTo(x+95,y);ctx.fill()}
